marker_key='AST' and coalesce(r.sex_specific,'')='' and r.range_min=41 and r.level='watch' and r.range_max=80) or (r.biomarker_key='ALT' and coalesce(r.sex_specific,'')='' and r.range_min=0 and r.level='normal' and r.range_max=40) or (r.biomarker_key='ALT' and coalesce(r.sex_specific,'')='' and r.range_min=41 and r.level='watch' and r.range_max=80) or (r.biomarker_key='GGT' and coalesce(r.sex_specific,'')='M' and r.range_min=0 and r.level='normal' and r.range_max=63) or (r.biomarker_key='GGT' and coalesce(r.sex_specific,'')='F' and r.range_min=0 and r.level='normal' and r.range_max=35) or (r.biomarker_key='creatinine' and coalesce(r.sex_specific,'')='' and r.range_min=0.6 and r.level='normal' and r.range_max=1.2) or (r.biomarker_key='creatinine' and coalesce(r.sex_specific,'')='' and r.range_min=1.21 and r.level='watch' and r.range_max=1.5) or (r.biomarker_key='BMI' and coalesce(r.sex_specific,'')='' and r.range_min=0 and r.level='low' and r.range_max=18.4) or (r.biomarker_key='BMI' and coalesce(r.sex_specific,'')='' and r.range_min=18.5 and r.level='normal' and r.range_max=22.9) or (r.biomarker_key='BMI' and coalesce(r.sex_specific,'')='' and r.range_min=23 and r.level='watch' and r.range_max=24.9) or (r.biomarker_key='hemoglobin' and coalesce(r.sex_specific,'')='M' and r.range_min=0 and r.level='low' and r.range_max=12.9) or (r.biomarker_key='hemoglobin' and coalesce(r.sex_specific,'')='F' and r.range_min=0 and r.level='low' and r.range_max=11.9) or (r.biomarker_key='TSH' and coalesce(r.sex_specific,'')='' and r.range_min=0 and r.level='low' and r.range_max=0.39) or (r.biomarker_key='TSH' and coalesce(r.sex_specific,'')='' and r.range_min=0.4 and r.level='normal' and r.range_max=4.5) or (r.biomarker_key='vitamin_D' and coalesce(r.sex_specific,'')='' and r.range_min=0 and r.level='low' and r.range_max=19) or (r.biomarker_key='vitamin_D' and coalesce(r.sex_specific,'')='' and r.range_min=20 and r.level='watch' and r.range_max=29);

